CREATE TRIGGER `staff_users_keep_owner` BEFORE UPDATE OF role, status ON `staff_users` WHEN OLD.role = 'owner' AND OLD.status = 'active' AND (NEW.role <> 'owner' OR NEW.status <> 'active') AND NOT EXISTS (SELECT 1 FROM staff_users WHERE role = 'owner' AND status = 'active' AND id <> OLD.id) BEGIN SELECT RAISE(ABORT, 'at least one active owner is required'); END;
